SELECT 
FROM resource_management
WHERE deleted = 0

    AND resource_name LIKE CONCAT('%', #{resourceName}, '%')


    AND resource_type = #{resourceType}


    AND category_id = #{categoryId}



    AND (category_id = #{level1CategoryId} OR category_path LIKE CONCAT(#{level1CategoryId}, '/%') OR category_path LIKE CONCAT('%/', #{level1CategoryId}, '/%'))



    AND category_id = #{level2CategoryId}


    AND status = #{status}


    AND scope = #{scope}


    AND recommended = #{recommended}


    AND pinned = #{pinned}


    AND uploader LIKE CONCAT('%', #{uploader}, '%')


    AND school_uid = #{schoolUid}

ORDER BY pinned DESC, create_time DESC

